class LSMTree:
    _TOMBSTONE = object()

    def __init__(self, flush_threshold=3):
        self.flush_threshold = flush_threshold
        self.memtable = {}
        self.sstables = []

    def put(self, key, value):
        self.memtable[key] = value
        if len(self.memtable) >= self.flush_threshold:
            self.flush()

    def delete(self, key):
        self.memtable[key] = self._TOMBSTONE
        if len(self.memtable) >= self.flush_threshold:
            self.flush()

    def get(self, key):
        if key in self.memtable:
            val = self.memtable[key]
            return None if val is self._TOMBSTONE else val

        for sstable in self.sstables:
            if key in sstable:
                val = sstable[key]
                return None if val is self._TOMBSTONE else val
        return None

    def flush(self):
        if not self.memtable:
            return
        sorted_items = dict(sorted(self.memtable.items()))
        self.sstables.insert(0, sorted_items)
        self.memtable = {}

    def compact(self):
        if len(self.sstables) <= 1:
            return
        merged = {}
        for sstable in reversed(self.sstables):
            merged.update(sstable)
        final = {k: v for k, v in sorted(merged.items()) if v is not self._TOMBSTONE}
        self.sstables = [final]
